  wire clk;
  wire clk_ibuf_s;
  wire rx_clk_in_n;
  wire rx_clk_in_p;

  (* BOX_TYPE = "PRIMITIVE" *) 
  BUFG i_clk_gbuf
       (.I(clk_ibuf_s),
